using ChogGames.Core.Nfts;
using ChogGames.Core.Wallets;

namespace ChogGames.Core.Players;

/// <summary>
/// A person playing on the platform. The id is generated by the server and is never accepted
/// from a client as proof of identity; identity always comes from the authenticated session.
/// </summary>
public sealed class Player
{
    public Guid Id { get; private set; }

    public string DisplayName { get; private set; } = string.Empty;

    public string AvatarId { get; private set; } = DefaultAvatar.Classic.Id;

    public PlayerKind Kind { get; private set; }

    /// <summary>Lowercase address bound by a verified wallet sign-in; null for guests. One wallet per player.</summary>
    public string? WalletAddress { get; private set; }

    public DateTimeOffset CreatedAt { get; private set; }

    /// <summary>
    /// Preferred character for the next match (NFT-004/NFT-005): a standard Chog or one NFT. A preference only;
    /// NFT ownership is verified again before a match starts (NFT-008).
    /// </summary>
    public CharacterKind SelectedCharacterKind { get; private set; } = CharacterKind.Standard;

    /// <summary>A <see cref="DefaultAvatar"/> id for standard Chogs, a canonical token id for NFTs.</summary>
    public string SelectedCharacterId { get; private set; } = DefaultAvatar.Classic.Id;

    /// <summary>Completed matches. Maintained by the server when matches finish, never by clients.</summary>
    public int GamesPlayed { get; private set; }

    /// <summary>Completed matches won. Maintained by the server when matches finish, never by clients.</summary>
    public int Wins { get; private set; }

    private Player()
    {
    }

    public static Player CreateGuest(PlayerDisplayName displayName, DateTimeOffset now) => new()
    {
        Id = Guid.NewGuid(),
        DisplayName = displayName.Value,
        AvatarId = DefaultAvatar.Classic.Id,
        Kind = PlayerKind.Guest,
        CreatedAt = now,
    };

    /// <summary>A new player for a wallet that is not yet bound to anyone, used when the caller already has another wallet.</summary>
    public static Player CreateForWallet(WalletAddress wallet, PlayerDisplayName displayName, DateTimeOffset now) => new()
    {
        Id = Guid.NewGuid(),
        DisplayName = displayName.Value,
        AvatarId = DefaultAvatar.Classic.Id,
        Kind = PlayerKind.Wallet,
        WalletAddress = wallet.Value,
        CreatedAt = now,
    };

    /// <summary>Upgrades a guest to a wallet player, keeping its name, avatar and stats (DEC-004 sign-in binding).</summary>
    public void BindWallet(WalletAddress wallet)
    {
        if (Kind != PlayerKind.Guest || WalletAddress is not null)
        {
            throw new InvalidOperationException("Only a guest without a wallet can be bound to a wallet.");
        }

        Kind = PlayerKind.Wallet;
        WalletAddress = wallet.Value;
    }

    public void Rename(PlayerDisplayName displayName) => DisplayName = displayName.Value;

    public void ChangeAvatar(DefaultAvatar avatar) => AvatarId = avatar.Id;

    public void SelectStandardCharacter(DefaultAvatar character)
    {
        SelectedCharacterKind = CharacterKind.Standard;
        SelectedCharacterId = character.Id;
    }

    /// <summary>Selects an NFT whose ownership by this player's wallet the caller has just verified on chain.</summary>
    public void SelectNftCharacter(NftTokenId tokenId)
    {
        if (Kind != PlayerKind.Wallet)
        {
            throw new InvalidOperationException("Only a wallet player can select an NFT character.");
        }

        SelectedCharacterKind = CharacterKind.Nft;
        SelectedCharacterId = tokenId.ToString();
    }
}

public enum PlayerKind
{
    Guest,
    Wallet,
}

public enum CharacterKind
{
    Standard,
    Nft,
}
